  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/**
 * Drops every document for one tenant. A rebuild starts here so leftovers
 * (archived subjects, deleted comments, rows the page walk will not re-add)
 * cannot survive, and so another tenant's documents are never touched.
 */
export async function deleteOrgSearchDocuments(orgId: OrgId): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .run();
}

