/**
 * A project is searchable only while it is live. An archived project is
 * removed, so a later restore can put the current row back.
 */
export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (!isLive(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

/**
 * An issue is searchable only while the issue and its project are both live.
 * Otherwise the document is removed. Callers that archive or restore a parent
 * also re-index the issue's comments; this function only owns the issue row.
 */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!isLive(issue) || project === null || !isLive(project)) {
    await removeFromIndex(orgId, "issue", issue.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

/**
 * A comment is searchable only while the comment, its issue and that issue's
 * project are all live. Deleted comments and comments under an archived issue
 * or project are removed rather than upserted.
 */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  if (!isLive(comment)) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  if (issue === null || !isLive(issue)) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (project === null || !isLive(project)) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue.projectId,
  );
}

