        return;
      }
      await syncComment(payload.orgId, payload.subjectId as CommentId);
    }),
  ];

/**
 * Re-reads one issue and applies the visibility rule to it and every comment
 * on it. Archiving the issue, editing it under an archived project, or
 * restoring a parent all come through here, so comments cannot outlive the
 * issue or the project in the index.
 */
async function syncIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue) {
    await indexIssue(orgId, issue);
  } else {
    await removeFromIndex(orgId, "issue", issueId);
  }

  await eachPage((cursor) =>
    commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: true,
      limit: INDEX_PAGE_SIZE,
      cursor,
    }),
    (comment) => indexComment(orgId, comment),
  );
}

/**
 * Re-reads one comment and indexes or removes it. A deleted comment is archived
 * rather than hard-deleted, so the row is usually still there and `indexComment`
 * is what drops it.
 */
async function syncComment(orgId: OrgId, commentId: CommentId): Promise<void> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment) {
    await indexComment(orgId, comment);
    return;
  }
  await removeFromIndex(orgId, "comment", commentId);
}

/**
 * Re-reads a project and then every issue and comment under it. Restoring a
 * project brings back only what is still live: issues archived on their own or
 * archived with the project stay out, and so do their comments.
 */
async function syncProject(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) {
    await indexProject(orgId, project);
  } else {
    await removeFromIndex(orgId, "project", projectId);
  }

  await eachPage(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        limit: INDEX_PAGE_SIZE,
        cursor,
        includeArchived: true,
      }),
    async (issue) => {
      await indexIssue(orgId, issue);
      await eachPage(
        (cursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: true,
            limit: INDEX_PAGE_SIZE,
            cursor,
          }),
        (comment) => indexComment(orgId, comment),
      );
    },
  );
}

async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

