/**
 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. Repositories cap a page at this size. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Replaces one tenant's index with exactly the documents the visibility rule
 * allows. Every project, issue and comment is handed to the index writers,
 * including archived rows, and those writers drop anything that is not live
 * all the way up to the project. The walk is paged so a large workspace is
 * covered in full. The opening delete is scoped to this org, so another
 * tenant's documents stay as they are, and so stale rows the writers will
 * not re-add cannot survive.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteOrgSearchDocuments(orgId);

    await eachPage(
      (cursor) =>
        projectRepo.listProjects({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (project) => {
        await indexOne(result, () => indexProject(orgId, project), {
          projectId: project.id,
        });
      },
    );

    await eachPage(
      (cursor) =>
        issueRepo.listIssues({
          orgId,
          limit: PAGE_SIZE,
          cursor,
          includeArchived: true,
        }),
      async (issue) => {
        await indexOne(result, () => indexIssue(orgId, issue), {
          issueId: issue.id,
        });

        await eachPage(
          (cursor) =>
            commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: true,
              limit: PAGE_SIZE,
              cursor,
            }),
          async (comment) => {
            await indexOne(result, () => indexComment(orgId, comment), {
              issueId: issue.id,
              commentId: comment.id,
            });
          },
        );
      },
    );
  });
}

async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

async function indexOne(
  result: JobResult,
  work: () => Promise<void>,
  fields: Record<string, string>,
): Promise<void> {
  try {
    await work();
    result.processed += 1;
  } catch (error) {
    result.failed += 1;
    logger.error("failed to index", {
      ...fields,
      reason: error instanceof Error ? error.message : String(error),
    });
  }
}

