/**
 * Re-reads one comment and indexes or removes it. A deleted comment is archived
 * rather than hard-deleted, so the row is usually still there and `indexComment`
 * is what drops it.
 */
async function syncComment(orgId: OrgId, commentId: CommentId): Promise<void> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment) {
