/**
 * Re-reads a project and then every issue and comment under it. Restoring a
 * project brings back only what is still live: issues archived on their own or
 * archived with the project stay out, and so do their comments.
 */
async function syncProject(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) {
    await indexProject(orgId, project);
  } else {
    await removeFromIndex(orgId, "project", projectId);
  }

  await eachPage(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        limit: INDEX_PAGE_SIZE,
        cursor,
        includeArchived: true,
      }),
    async (issue) => {
      await indexIssue(orgId, issue);
      await eachPage(
        (cursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: true,
            limit: INDEX_PAGE_SIZE,
            cursor,
          }),
        (comment) => indexComment(orgId, comment),
      );
    },
  );
}

async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

