/**
 * Temporary coverage for archive/restore/rebuild visibility. Deleted after the run.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { eq } from "drizzle-orm";
import { getDb, searchIndex } from "@/server/db";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function hits(actor: Actor, orgId: OrgId, q: string, kinds: Array<"issue" | "comment" | "project"> = ["issue", "comment", "project"]) {
  return searchService.search(actor, {
    orgId,
    q,
    kinds,
    limit: 100,
    cursor: null,
  });
}

describe("search visibility", () => {
  it("hides comments with an archived issue, hides a project subtree, restores only what stayed live, and rebuilds one workspace exactly", async () => {
    const tenant = await createTenant("vis", "growth");
    const other = await createTenant("visother", "growth");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "VisibleIssueMarker" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "VisibleCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });

    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleIssueMarker")).total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleCommentMarker")).total).toBe(1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleCommentMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleCommentMarker")).items).toHaveLength(0);

