import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

async function hits(actor: Actor, orgId: OrgId, q: string, kinds: Array<"issue" | "comment" | "project"> = ["issue", "comment", "project"]) {
  return searchService.search(actor, {
    orgId,
    q,
    kinds,
    limit: 100,
    cursor: null,
  });
}

describe("search visibility", () => {
  it("hides comments with an archived issue, hides a project subtree, restores only what stayed live, and rebuilds one workspace exactly", async () => {
    const tenant = await createTenant("vis", "growth");
    const other = await createTenant("visother", "growth");

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "VisibleIssueMarker" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "VisibleCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });

    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleIssueMarker")).total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleCommentMarker")).total).toBe(1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleCommentMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleCommentMarker")).items).toHaveLength(0);

    const kept = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "KeptIssueMarker" }),
    );
    const keptComment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      body: "KeptCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    const alone = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "AloneArchivedMarker" }),
    );
    const aloneComment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: alone.id,
      body: "AloneCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, alone.id);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    expect((await hits(tenant.actors.member, tenant.org.id, "KeptIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "KeptCommentMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, tenant.project.name)).total).toBe(0);

    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      body: "PostedAfterArchiveMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: kept.id,
      title: "EditedAfterArchiveMarker",
    });
    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: keptComment.id,
      body: "CommentEditedAfterArchiveMarker",
    });

    expect((await hits(tenant.actors.member, tenant.org.id, "PostedAfterArchiveMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "EditedAfterArchiveMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "CommentEditedAfterArchiveMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "KeptIssueMarker")).total).toBe(0);

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id);

    const restoredIssue = await hits(tenant.actors.member, tenant.org.id, "EditedAfterArchiveMarker");
    expect(restoredIssue.total).toBe(1);
    expect(restoredIssue.items[0]).toMatchObject({ kind: "issue", id: kept.id });
    expect((await hits(tenant.actors.member, tenant.org.id, "CommentEditedAfterArchiveMarker")).total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "PostedAfterArchiveMarker")).total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "AloneArchivedMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "AloneCommentMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, tenant.project.name)).total).toBe(1);

    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: keptComment.id,
    });
    expect((await hits(tenant.actors.member, tenant.org.id, "CommentEditedAfterArchiveMarker")).total).toBe(0);

    const cascaded = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "CascadeProjectMarker",
      slug: "cascade",
      key: "CAS",
      description: "CascadeDescMarker",
      visibility: "org",
      leadId: null,
      color: "#112233",
      targetDate: null,
    });
    const cascadedIssue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, cascaded.id, { title: "CascadeIssueMarker" }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: cascadedIssue.id,
      body: "CascadeCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: cascaded.id,
      archiveIssues: true,
    });
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeProjectMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeCommentMarker")).total).toBe(0);

    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, cascaded.id);
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeProjectMarker")).total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeCommentMarker")).total).toBe(0);

    await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: cascaded.id,
      name: "RenamedCascadeMarker",
    });
    expect((await hits(tenant.actors.member, tenant.org.id, "RenamedCascadeMarker")).total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeProjectMarker")).total).toBe(0);

    const bulkIssueIds: string[] = [];
    for (let i = 0; i < 105; i += 1) {
      const created = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: `IssueBulkMarker ${String(i).padStart(3, "0")}`,
        }),
      );
      bulkIssueIds.push(created.id);
    }
    const commented = bulkIssueIds[0]!;
    for (let i = 0; i < 105; i += 1) {
      await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: commented as never,
        body: `CommentBulkMarker ${String(i).padStart(3, "0")}`,
        parentId: null,
        mentionedUserIds: [],
      });
    }
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, bulkIssueIds[1] as never);
    const deleted = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: commented as never,
      body: "DeletedBulkCommentMarker",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.deleteComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: deleted.id,
    });

    const otherIssue = await issueService.createIssue(
      other.actors.member,
      issueInput(other.org.id, other.project.id, { title: "OtherOrgMarker" }),
    );
    const otherBefore = getDb()
      .select()
      .from(searchIndex)
      .where(eq(searchIndex.orgId, other.org.id))
      .all();

    await searchRepo.upsertSearchDocument(
      tenant.org.id,
      "issue",
      "ghost-subject",
      "GhostShouldVanishMarker",
      null,
    );
    await searchRepo.upsertSearchDocument(
      tenant.org.id,
      "issue",
      bulkIssueIds[1]!,
      "IssueBulkMarker 001",
      tenant.project.id,
    );
    await searchRepo.upsertSearchDocument(
      tenant.org.id,
      "comment",
      deleted.id,
      "DeletedBulkCommentMarker",
      tenant.project.id,
    );
    await searchRepo.upsertSearchDocument(
      tenant.org.id,
      "project",
      cascaded.id,
      "ArchivedProjectContentShouldNotReturn",
      cascaded.id,
    );

    const job = await runSearchReindexJob(tenant.org.id);
    expect(job.failed).toBe(0);

    const otherAfter = getDb()
      .select()
      .from(searchIndex)
      .where(eq(searchIndex.orgId, other.org.id))
      .all();
    expect(otherAfter).toEqual(otherBefore);
    expect((await hits(other.actors.member, other.org.id, "OtherOrgMarker")).items[0]).toMatchObject({
      id: otherIssue.id,
    });

    expect((await hits(tenant.actors.member, tenant.org.id, "GhostShouldVanishMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "DeletedBulkCommentMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "ArchivedProjectContentShouldNotReturn")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "CascadeIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "VisibleIssueMarker")).total).toBe(0);
    expect((await hits(tenant.actors.member, tenant.org.id, "AloneArchivedMarker")).total).toBe(0);

    const bulkIssues = await hits(tenant.actors.member, tenant.org.id, "IssueBulkMarker", ["issue"]);
    expect(bulkIssues.total).toBe(104);
    const oldest = await hits(tenant.actors.member, tenant.org.id, "IssueBulkMarker 000", ["issue"]);
    expect(oldest.total).toBe(1);
    const newest = await hits(tenant.actors.member, tenant.org.id, "IssueBulkMarker 104", ["issue"]);
    expect(newest.total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "IssueBulkMarker 001", ["issue"])).total).toBe(0);

    const bulkComments = await hits(tenant.actors.member, tenant.org.id, "CommentBulkMarker", ["comment"]);
    expect(bulkComments.total).toBe(105);
    expect((await hits(tenant.actors.member, tenant.org.id, "CommentBulkMarker 000", ["comment"])).total).toBe(1);
    expect((await hits(tenant.actors.member, tenant.org.id, "CommentBulkMarker 104", ["comment"])).total).toBe(1);

    const indexed = await searchRepo.countIndexed(tenant.org.id);
    const otherIndexed = await searchRepo.countIndexed(other.org.id);
    expect(otherIndexed).toBe(otherBefore.length);
    expect(indexed).toBeGreaterThan(200);
  }, 120_000);
});
